package fraymus.workspace;
import org.json.*;
import java.util.*;
/** Reconstruct all bodies and authorized native wrenches, then check every retained pose. */
final class PoseVerify {
 static final String CONTACT_METHOD="actual persistent native solver manifold with positive normal impulse";
 static double norm(JSONArray a){return ObserverGeometry.norm(SpatialScene.vector(a,100));}
 static void close(double a,double b,double tolerance,String message){if(!Double.isFinite(a)||!Double.isFinite(b)||Math.abs(a-b)>tolerance)throw new IllegalStateException(message);}
 static double distance(JSONArray a,JSONArray b){return ObserverGeometry.norm(ObserverGeometry.sub(SpatialScene.vector(a,30),SpatialScene.vector(b,30)));}
 static void quaternion(JSONArray q){if(q.length()!=4)throw new IllegalStateException("Quaternion size changed");double n=0;for(Object raw:q){if(!(raw instanceof Number v)||!Double.isFinite(v.doubleValue()))throw new IllegalStateException("Nonfinite quaternion");n+=v.doubleValue()*v.doubleValue();}close(n,1,.001,"Invalid native quaternion");}
 static JSONObject verify(JSONObject run){
  var scene=run.getJSONObject("definition");var plan=run.getJSONObject("plan");PosePlan.verify(scene,plan);if(!run.getString("controllerVersion").equals(PosePhysics.VERSION))throw new IllegalStateException("Pose controller version changed");var parsed=SpatialScene.parse(scene.getString("sourceText"),scene.getString("id"));for(String key:parsed.keySet())if(!new JSONObject().put("v",parsed.get(key)).similar(new JSONObject().put("v",scene.get(key))))throw new IllegalStateException("Original source changed");
  var positions=new LinkedHashMap<String,double[]>();var rotations=new LinkedHashMap<String,JSONArray>();var protectedPosition=new LinkedHashMap<String,double[]>();var protectedRotation=new LinkedHashMap<String,JSONArray>();var allIds=new HashSet<String>();var selected=new HashSet<String>();for(Object raw:plan.getJSONArray("orderedTargets"))selected.add(((JSONObject)raw).getString("objectId"));for(Object raw:scene.getJSONArray("objects")){var o=(JSONObject)raw;allIds.add(o.getString("id"));if(o.getDouble("massKg")>0){double[] p=SpatialScene.vector(o.getJSONArray("position"),30);positions.put(o.getString("id"),p);protectedPosition.put(o.getString("id"),p.clone());rotations.put(o.getString("id"),o.getJSONArray("rotation"));protectedRotation.put(o.getString("id"),o.getJSONArray("rotation"));}}
  int tick=0,grabs=0,releases=0,resumes=0,contactPoints=0,eventIndex=0;String active="";double effort=0,torqueEffort=0,work=0,angularWork=0,maxForce=0,maxTorque=0,maxBystander=0,maxBystanderAngle=0,maxInactive=0,maxInactiveAngle=0,restorePosition=0,restoreVelocity=0,restoreRotation=0;
  var events=run.getJSONArray("events");var samples=run.getJSONArray("samples");var force=new JSONArray(new int[]{0,0,0});var torque=new JSONArray(new int[]{0,0,0});
  for(Object raw:samples){var sample=(JSONObject)raw;for(Object value:sample.getJSONArray("integration")){var row=(JSONArray)value;if(row.length()!=7||row.getInt(0)!=++tick)throw new IllegalStateException("Missing native pose integration tick");
    while(eventIndex<events.length()&&events.getJSONObject(eventIndex).getInt("tick")<tick){var e=events.getJSONObject(eventIndex++);switch(e.getString("kind")){case "grab"->{if(!active.isEmpty()||!selected.contains(e.getString("objectId")))throw new IllegalStateException("Unauthorized/repeated virtual grip");active=e.getString("objectId");grabs++;}case "release"->{if(!active.equals(e.getString("objectId"))||!e.getJSONObject("before").similar(e.getJSONObject("after")))throw new IllegalStateException("Release changed native pose or velocities");active="";releases++;}case "failed"->active="";case "stage-complete","finished"->{}case "resume"->{resumes++;var expected=e.getJSONObject("expected");var actual=e.getJSONObject("actualInitialization");for(String id:positions.keySet()){var a=ContactPhysics.dynamic(expected.getJSONArray("bodies"),id);var b=ContactPhysics.dynamic(actual.getJSONArray("bodies"),id);restorePosition=Math.max(restorePosition,distance(a.getJSONArray("position"),b.getJSONArray("position")));restoreVelocity=Math.max(restoreVelocity,Math.max(distance(a.getJSONArray("velocity"),b.getJSONArray("velocity")),distance(a.getJSONArray("angularVelocity"),b.getJSONArray("angularVelocity"))));restoreRotation=Math.max(restoreRotation,PosePlan.angle(a.getJSONArray("rotation"),b.getJSONArray("rotation")));}if(!expected.getJSONObject("controller").similar(actual.getJSONObject("controller")))throw new IllegalStateException("Full pose controller did not restore");}default->throw new IllegalStateException("Unknown pose lifecycle event");}}
    if(!row.getString(1).equals(active))throw new IllegalStateException("Unauthorized native actuator body");force=row.getJSONArray(2);torque=row.getJSONArray(3);double f=norm(force),t=norm(torque);maxForce=Math.max(maxForce,f);maxTorque=Math.max(maxTorque,t);if(f>plan.getJSONObject("intent").getDouble("forceLimitN")+.0001||t>plan.getJSONObject("intent").getDouble("torqueLimitNm")+.0001||!run.getBoolean("orientationControl")&&t>1e-7||active.isEmpty()&&(f>0||t>0))throw new IllegalStateException("Original native wrench authority/limits changed");
    var ds=row.getJSONArray(6);if(ds.length()!=positions.size())throw new IllegalStateException("A dynamic body vanished from native trace");var seen=new HashSet<String>();double observedWork=0,observedAngular=0;
    for(Object data:ds){var d=(JSONArray)data;String id=d.getString(0);if(d.length()!=3||!positions.containsKey(id)||!seen.add(id))throw new IllegalStateException("Duplicate/foreign pose body delta");var dp=SpatialScene.vector(d.getJSONArray(1),1);var q=d.getJSONArray(2);quaternion(q);double[] p=positions.get(id);for(int k=0;k<3;k++)p[k]+=dp[k];if(id.equals(active)){for(int k=0;k<3;k++)observedWork+=force.getDouble(k)*dp[k];double[] dr=PosePlan.rotationError(q,rotations.get(id));for(int k=0;k<3;k++)observedAngular+=torque.getDouble(k)*dr[k];protectedPosition.put(id,p.clone());protectedRotation.put(id,q);}else{double drift=ObserverGeometry.norm(ObserverGeometry.sub(p,protectedPosition.get(id))),angle=PosePlan.angle(q,protectedRotation.get(id));maxInactive=Math.max(maxInactive,drift);maxInactiveAngle=Math.max(maxInactiveAngle,angle);if(!selected.contains(id)){maxBystander=Math.max(maxBystander,drift);maxBystanderAngle=Math.max(maxBystanderAngle,angle);}}rotations.put(id,q);}
    close(observedWork,row.getDouble(4),1e-7,"Native linear work differs");close(observedAngular,row.getDouble(5),1e-7,"Native angular work differs");effort+=f*BulletRamp.DT;torqueEffort+=t*BulletRamp.DT;work+=observedWork;angularWork+=observedAngular;
   }
   if(sample.getInt("tick")!=tick||!sample.getString("contactMethod").equals(CONTACT_METHOD))throw new IllegalStateException("Native pose sample clock/observation authority changed");close(sample.getDouble("timeS"),tick*BulletRamp.DT,1e-10,"Pose time changed");close(sample.getDouble("effortNs"),effort,1e-5,"Pose effort changed");close(sample.getDouble("torqueEffortNms"),torqueEffort,1e-5,"Pose torque effort changed");close(sample.getDouble("workJ"),work,1e-5,"Pose work changed");close(sample.getDouble("angularWorkJ"),angularWork,1e-5,"Pose angular work changed");if(!sample.getJSONArray("force").similar(force)||!sample.getJSONArray("torque").similar(torque))throw new IllegalStateException("Pose sampled wrench changed");
   if(sample.getJSONArray("bodies").length()!=positions.size())throw new IllegalStateException("Missing observed dynamic body");for(String id:positions.keySet()){var b=ContactPhysics.dynamic(sample.getJSONArray("bodies"),id);close(distance(new JSONArray(positions.get(id)),b.getJSONArray("position")),0,2e-6,"Native pose displacement ledger differs");close(PosePlan.angle(rotations.get(id),b.getJSONArray("rotation")),0,.0001,"Native orientation ledger differs");SpatialScene.vector(b.getJSONArray("velocity"),100);SpatialScene.vector(b.getJSONArray("angularVelocity"),100);if(b.getInt("initializationPoseWrites")!=1)throw new IllegalStateException("Pose writes outside initialization");}
   for(Object value:sample.getJSONArray("contacts")){var c=(JSONObject)value;if(!allIds.contains(c.getString("a"))||!allIds.contains(c.getString("b"))||c.getString("a").equals(c.getString("b"))||c.getDouble("distanceM")>.015||!Double.isFinite(c.getDouble("distanceM"))||c.getDouble("normalImpulseNs")<=1e-6||!Double.isFinite(c.getDouble("normalImpulseNs")))throw new IllegalStateException("Invalid actual native solver contact");contactPoints++;}
  }
  if(tick==0||samples.isEmpty())return new JSONObject().put("passed",false).put("nativeTicks",0);
  var last=samples.getJSONObject(samples.length()-1);if(!last.similar(run.getJSONObject("final")))throw new IllegalStateException("Final pose differs from committed native sample");double maxPosition=0,maxAngle=0,maxSpeed=0,maxAngular=0;var results=new JSONArray();for(Object raw:plan.getJSONArray("orderedTargets")){var goal=(JSONObject)raw;var b=ContactPhysics.dynamic(last.getJSONArray("bodies"),goal.getString("objectId"));double p=distance(goal.getJSONArray("positionM"),b.getJSONArray("position")),a=PosePlan.angle(goal.getJSONArray("rotation"),b.getJSONArray("rotation")),v=norm(b.getJSONArray("velocity")),w=norm(b.getJSONArray("angularVelocity"));maxPosition=Math.max(maxPosition,p);maxAngle=Math.max(maxAngle,a);maxSpeed=Math.max(maxSpeed,v);maxAngular=Math.max(maxAngular,w);results.put(new JSONObject().put("sourceId",goal.getString("sourceId")).put("positionErrorM",p).put("angleErrorDeg",a).put("speedMps",v).put("angularSpeedRadps",w));}
  boolean passed=last.getJSONObject("controller").getString("phase").equals("finished")&&last.getJSONObject("controller").getString("grippingId").isEmpty()&&maxPosition<=.1&&maxAngle<=5&&maxSpeed<=.2&&maxAngular<=.2&&maxInactive<=.05&&maxInactiveAngle<=5&&grabs==plan.getJSONArray("orderedTargets").length()&&releases==grabs&&restorePosition<2e-6&&restoreVelocity<2e-6&&restoreRotation<.0001;
  return new JSONObject().put("passed",passed).put("scope",PosePlan.SCOPE).put("nativePhysics",true).put("nativeTicks",tick).put("timeS",tick*BulletRamp.DT).put("targets",results).put("maxPositionErrorM",maxPosition).put("maxAngleErrorDeg",maxAngle).put("maxSpeedMps",maxSpeed).put("maxAngularSpeedRadps",maxAngular).put("maxBystanderDriftM",maxBystander).put("maxBystanderAngleDeg",maxBystanderAngle).put("maxInactiveDriftM",maxInactive).put("maxInactiveAngleDeg",maxInactiveAngle).put("maxForceN",maxForce).put("maxTorqueNm",maxTorque).put("effortNs",effort).put("torqueEffortNms",torqueEffort).put("workJ",work).put("angularWorkJ",angularWork).put("grabs",grabs).put("releases",releases).put("contactPoints",contactPoints).put("resumes",resumes).put("maxRestorePositionErrorM",restorePosition).put("maxRestoreVelocityError",restoreVelocity).put("maxRestoreAngleErrorDeg",restoreRotation);
 }
}
